operation.add:
// FlexExt Product Custom Tabs Lite (Free Edition)
$data['custom_tab_lite'] = null;
if ($this->config->get('module_product_tabs_lite_status')) {
    $lite_lang_id = (int)$this->config->get('config_language_id');
    $lite_descs = $this->config->get('module_product_tabs_lite_description');
    $lite_title = '';
    $lite_desc = '';

    if (!empty($lite_descs[$lite_lang_id]['title'])) {
        $lite_title = $lite_descs[$lite_lang_id]['title'];
        $lite_desc = html_entity_decode($lite_descs[$lite_lang_id]['description'] ?? '', ENT_QUOTES, 'UTF-8');
    } elseif (is_array($lite_descs)) {
        foreach ($lite_descs as $ld) {
            if (!empty($ld['title'])) {
                $lite_title = $ld['title'];
                $lite_desc = html_entity_decode($ld['description'] ?? '', ENT_QUOTES, 'UTF-8');
                break;
            }
        }
    }

    if (!empty($lite_title) || !empty($lite_desc)) {
        $data['custom_tab_lite'] = array(
            'title'       => $lite_title,
            'icon'        => $this->config->get('module_product_tabs_lite_icon') ?: 'fa fa-ruler',
            'description' => $lite_desc
        );
    }
}

{% if custom_tab_lite %}
<li><a href="#tab-custom-lite" data-toggle="tab">{% if custom_tab_lite.icon %}<i class="{{ custom_tab_lite.icon }}"></i> {% endif %}{{ custom_tab_lite.title }}</a></li>
{% endif %}

{% if custom_tab_lite %}
<div class="tab-pane" id="tab-custom-lite"><div style="background:#fff; border:1px solid #e2e8f0; border-radius:6px; padding:18px; margin-bottom:15px;">{{ custom_tab_lite.description|raw }}</div></div>
{% endif %}
